//
// falcon_m65.sv
//
// The Falcon030 machine of MegaST: falcon_system (Falcon_MiSTer) with the
// MEGA65 parts the MiSTer framework (HPS, hps_io, DDR3) provides there:
//
//   - memory: falcon_sdram.v on the SDRAM pins of sdram_m65.v (sd_*_o, sd_din_i)
//   - TOS: MegaST's tos_loader (16-bit words at the 68000 address, the even
//     byte in bits 15..8) -> the Falcon's byte loader (ld_*); TOS is at $E00000
//   - keyboard: MegaST's ST keyboard matrix (keyboard.vhd) -> PS/2 events for
//     the Falcon's IKBD (falcon_kbd_map.v, generated by tools/make_falcon_kbd.py)
//   - drives 0..3 (floppy A/B, hard disk 0/1): fdc_bridge.vhd's 16-bit
//     sector buffer interface (even byte in bits 7..0) -> the Falcon's 8-bit
//     one (one 512 byte sector per request: the floppy and IDE controllers
//     never ask for more, the SCSI one is built with BLK_MAX = 1). The hard
//     disks are IDE master/slave or, with hd_scsi, SCSI ID 0/1 (for drivers
//     without IDE, such as ICD)
//
// The machine is held in reset while the Falcon is not selected.
//
// This machine is based on Falcon_MiSTer (see CORE/Falcon_MiSTer/ORIGIN.md)
// MEGA65 port done by Chris Freeman in 2026, licensed under GPL v3

module falcon_m65 #(
	parameter CLK_HZ = 32083333
) (
	input             clk_32,
	input             clk_96,
	input             reset,          // machine reset
	input             cold_reset,     // cold reset (power on, TOS loaded)
	input             por,            // power on / Falcon not selected: also resets the memory arbiter

	input       [3:0] ram_mb,         // ST-RAM in MB (4 or 14)
	input       [1:0] fast_n,         // Fast RAM (TT-RAM) at $01000000 in 16 MB blocks, 0..3 (falcon_cpubus.sv)
	input       [1:0] monitor,        // 0 mono, 1 RGB, 2 VGA, 3 TV
	input             cpu_turbo,      // 1: CPU at 32 MHz; 0: Falcon 16/8 MHz
	input       [7:0] tos_lang,       // NVRAM language and keyboard (0 US, 3 UK, see falcon_nvram.sv)
	input             hd_scsi,        // hard disks 0/1 on SCSI ID 0/1 instead of IDE master/slave

	// TOS loader (MegaST tos_loader.vhd; written while the machine is in reset)
	input      [23:1] dio_addr,
	input      [15:0] dio_data,
	input             dio_strobe,     // toggles for each word
	output reg        dio_strobe_ack, // follows dio_strobe when the word is written
	input             cart_loaded,    // a cartridge image is loaded at $FA0000 (0: ejected or none)

	// NVRAM on the SD card (/atarist/fcnvram, firmware nvram.asm): port B of a 64 byte dual port
	// RAM (mega65.vhd) that the firmware fills from the file before the machine starts and saves
	// when byte 62 changes. Bytes 0..49 = NVRAM bytes 14..63, 62 = change counter, 63 = $A5 when
	// bytes 0..49 are valid. One clock of read latency.
	output reg  [5:0] nvb_addr,
	output reg  [7:0] nvb_din,
	output reg        nvb_we,
	input       [7:0] nvb_dout,

	// keyboard, mouse, joysticks, clock
	input     [119:0] kbd_matrix_n,   // ST keyboard matrix, low active, bit col*8+row
	input      [24:0] ps2_mouse,      // MiSTer format
	input      [31:0] joy0,           // MiSTer format: 0 right, 1 left, 2 down, 3 up, 4 fire
	input      [31:0] joy1,
	input      [31:0] pad0,           // enhanced joystick ports A and B (joypads), MiSTer format
	input      [31:0] pad1,
	input      [15:0] ana0,           // paddles of the enhanced ports A and B: [7:0] X, [15:8] Y,
	input      [15:0] ana1,           // signed (MiSTer analog sticks)
	input      [64:0] rtc,

	// drives 0..3: fdc_bridge.vhd core side
	input       [3:0] img_mounted,
	input             img_readonly,
	input      [31:0] img_size,
	output    [127:0] sd_lba,         // drive i: bits 32*i+31 .. 32*i
	output      [3:0] sd_rd,
	output      [3:0] sd_wr,
	input       [3:0] sd_ack,
	input       [7:0] sd_buff_addr,   // 16-bit word address
	input      [15:0] sd_buff_dout,
	output     [63:0] sd_buff_din,    // drive i: bits 16*i+15 .. 16*i
	input             sd_buff_wr,

	// video, audio, LEDs
	output      [7:0] r,
	output      [7:0] g,
	output      [7:0] b,
	output            hsync,
	output            vsync,
	output            hblank,
	output            vblank,
	output            ce_pix,
	output     [15:0] audio_l,
	output     [15:0] audio_r,
	output            fdd_led,
	// the MEGA65's internal floppy drive as A: (real_fd, menu "Real floppy drive as A:"): its
	// WD1772 is wd1772_m65.v (as in the ST), all signals active high (m65_floppy_port.vhd)
	input             real_fd,
	input             fd_retry,       // menu "Floppy read assist"
	output            rfd_sel_a,
	output            rfd_motor,
	output            rfd_side,       // 1 = side 1
	output            rfd_dir_in,     // 1 = step in
	output            rfd_step,
	output            rfd_wgate,
	output            rfd_wdata,
	input             rfd_rdata,
	input             rfd_index,
	input             rfd_track0,
	input             rfd_wprot,
	input             midi_rx,        // MIDI and the serial port (MFP USART), idle 1
	output            midi_tx,
	input             ser_rx,
	output            ser_tx,
	output            hdd_led,
	output    [159:0] dbg,            // JTAG probe (falcon_system.sv)

	// SDRAM through the pin registers of sdram_m65.v
	input             sdram_start,    // sdram_m65.v has initialized the SDRAM and gave the pins away
	output      [3:0] sd_cmd_o,
	output     [12:0] sd_addr_o,
	output      [1:0] sd_ba_o,
	output      [1:0] sd_dqm_o,
	output     [15:0] sd_dout_o,
	output            sd_doe_o,
	input      [15:0] sd_din_i
);

// ---------------------------------------------------------------------------
// TOS loader: one word -> two bytes
// ---------------------------------------------------------------------------

reg        ld_wr = 1'b0;
reg [23:0] ld_addr;
reg  [7:0] ld_data;
wire       ld_busy;
reg  [1:0] ld_step = 2'd0;      // 0 idle, 1 even byte, 2 odd byte

// Without a cartridge its magic long at $FA0000 is cleared (after an eject the image would still
// be in the SDRAM and TOS would start it): 4 zero bytes through the loader, at the end of a power-on
// or when the cartridge is ejected
reg       cart_d = 1'b0, por_d = 1'b1;
reg [2:0] cclr = 3'd0;          // bytes still to clear (4..1)

always @(posedge clk_32) begin
	ld_wr <= 1'b0;
	cart_d <= cart_loaded;
	por_d  <= por;
	if (!cart_loaded && ((cart_d && !cart_loaded) || (por_d && !por))) cclr <= 3'd4;
	if (cart_loaded) cclr <= 3'd0;      // a cartridge came first (its own bytes are there)
	case (ld_step)
		2'd0: if (dio_strobe != dio_strobe_ack) ld_step <= 2'd1;
		      else if (cclr != 3'd0 && !cart_loaded && !ld_busy && !ld_wr) begin
			ld_wr   <= 1'b1;
			ld_addr <= 24'hFA0004 - {21'd0, cclr};
			ld_data <= 8'h00;
			cclr    <= cclr - 3'd1;
		      end
		2'd1: if (!ld_busy && !ld_wr) begin
			ld_wr   <= 1'b1;
			ld_addr <= {dio_addr, 1'b0};
			ld_data <= dio_data[15:8];
			ld_step <= 2'd2;
		end
		2'd2: if (!ld_busy && !ld_wr) begin
			ld_wr   <= 1'b1;
			ld_addr <= {dio_addr, 1'b1};
			ld_data <= dio_data[7:0];
			ld_step <= 2'd3;
		end
		2'd3: if (!ld_busy && !ld_wr) begin
			dio_strobe_ack <= dio_strobe;
			ld_step <= 2'd0;
		end
	endcase
end

// ---------------------------------------------------------------------------
// Keyboard: ST matrix changes -> PS/2 events (at most one per millisecond, the
// Falcon's IKBD takes one event at a time)
// ---------------------------------------------------------------------------

reg   [119:0] kbd_prev = {120{1'b1}};
reg     [6:0] kbd_idx = 7'd0;
reg    [15:0] kbd_gap = 16'd0;
reg    [10:0] ps2_key = 11'd0;
wire    [9:0] kbd_ps2;          // {valid, E0, code}
wire          kbd_now = kbd_matrix_n[kbd_idx];

falcon_kbd_map kbd_map (.idx(kbd_idx), .ps2(kbd_ps2));

always @(posedge clk_32) begin
	if (kbd_gap != 0) kbd_gap <= kbd_gap - 16'd1;
	else begin
		kbd_idx <= (kbd_idx == 7'd119) ? 7'd0 : kbd_idx + 7'd1;
		if (kbd_now != kbd_prev[kbd_idx]) begin
			kbd_prev[kbd_idx] <= kbd_now;
			if (kbd_ps2[9]) begin
				ps2_key <= {~ps2_key[10], ~kbd_now, kbd_ps2[8:0]};
				kbd_gap <= CLK_HZ / 1000;
			end
		end
	end
	if (reset) kbd_prev <= {120{1'b1}};   // keys held at the reset are sent again
end

// ---------------------------------------------------------------------------
// Drives 0..3: 16-bit sector buffer interface <-> the Falcon's 8-bit one
// ---------------------------------------------------------------------------

wire [31:0] f_lba[7];
wire  [6:0] f_rd, f_wr;
wire  [5:0] f_blk_cnt[7];
wire  [7:0] f_buff_din[7];
reg  [13:0] f_buff_addr;
reg   [7:0] f_buff_dout;
reg         f_buff_wr;
reg         wr_hi = 1'b0;       // the odd byte of a word from the bridge is still to be written
reg   [7:0] wr_addr;            // its word address (the bridge shows it for one clock only)
reg   [7:0] wr_hi_byte;
reg   [1:0] rd_cnt = 2'd0;      // reading the sector buffers: [1] = byte (0 even, 1 odd), 2 clocks each
reg   [1:0] rd_t1 = 2'd0, rd_t2 = 2'd0;   // {first clock of a byte, byte} of the address 1 and 2 clocks ago
reg   [7:0] rd_lo[4], rd_hi[4];

// The bridge reads a byte by its word address and waits (C_VD_DIN_WAIT) for the word in
// sd_buff_din. Each byte address is held for 2 clocks. The floppy buffer answers 2 clocks after
// an address (registered RAM), the IDE buffer registers the word and selects the byte by the
// address of the clock before: both are right 2 clocks after the first clock of a byte.
always @(posedge clk_32) begin
	f_buff_wr <= 1'b0;
	if (sd_buff_wr) begin
		// a word for the sector buffer: even byte now, odd byte in the next clock
		f_buff_addr <= {5'd0, sd_buff_addr, 1'b0};
		f_buff_dout <= sd_buff_dout[7:0];
		f_buff_wr   <= 1'b1;
		wr_hi       <= 1'b1;
		wr_addr     <= sd_buff_addr;
		wr_hi_byte  <= sd_buff_dout[15:8];
		rd_cnt      <= 2'd0;
	end
	else if (wr_hi) begin
		f_buff_addr <= {5'd0, wr_addr, 1'b1};
		f_buff_dout <= wr_hi_byte;
		f_buff_wr   <= 1'b1;
		wr_hi       <= 1'b0;
	end
	else begin
		f_buff_addr <= {5'd0, sd_buff_addr, rd_cnt[1]};
		rd_cnt      <= rd_cnt + 2'd1;
	end
	rd_t1 <= (sd_buff_wr || wr_hi) ? 2'b00 : {rd_cnt[0] == 1'b0, rd_cnt[1]};
	rd_t2 <= rd_t1;
end

// Hard disks 0/1 (drives 2/3) are IDE master/slave (Falcon slots 2/3) or SCSI ID 0/1 (slots 4/5).
// hd_scsi takes effect with a reset; the images mounted so far are then announced again: size 0
// to the controller they leave, their size to the one they move to (hd_*).
reg         hd_scsi_q = 1'b0;
reg   [1:0] hd_mnt = 2'b00;     // drives 2/3: an image is mounted
reg   [1:0] hd_ro;
reg  [31:0] hd_size[2];
reg   [2:0] hd_step = 3'd0;     // announcing again: 4 = drive 2 off, 3 = drive 2 on, 2 = 3 off, 1 = 3 on
wire        hd_d  = hd_step <= 3'd2;               // drive 3
wire        hd_on = hd_step[0];                    // to the new controller
reg   [6:0] s_mounted;          // to falcon_system
reg         s_ro;
reg  [31:0] s_size;

always @(posedge clk_32) begin
	s_mounted <= 7'd0;
	s_ro      <= img_readonly;
	s_size    <= img_size;
	if (img_mounted[2]) begin hd_mnt[0] <= |img_size; hd_ro[0] <= img_readonly; hd_size[0] <= img_size; end
	if (img_mounted[3]) begin hd_mnt[1] <= |img_size; hd_ro[1] <= img_readonly; hd_size[1] <= img_size; end
	if (hd_step != 3'd0) begin
		// (no new image comes in the few clocks of a reset)
		s_mounted[{1'b0, hd_on == hd_scsi_q, hd_d} + 3'd2] <= 1'b1;   // new SCSI or old SCSI: slot 4/5
		s_ro      <= hd_ro[hd_d];
		s_size    <= (hd_on && hd_mnt[hd_d]) ? hd_size[hd_d] : 32'd0;
		hd_step   <= hd_step - 3'd1;
	end
	else if (reset && hd_scsi != hd_scsi_q) begin
		hd_scsi_q <= hd_scsi;
		hd_step   <= 3'd4;
	end
	else
		s_mounted <= {1'b0, hd_scsi_q ? img_mounted[3:2] : 2'b00, hd_scsi_q ? 2'b00 : img_mounted[3:2],
		              img_mounted[1:0]};
end

// The SCSI targets fetch INQUIRY, READ CAPACITY and MODE SENSE answers from Main_MiSTer as reads of
// "window" blocks at LBA $7Exxxxxx (and send MODE SELECT as a write at $7Dxxxxxx). The MEGA65 has
// no Main: such a request is acknowledged here without data (response length 0), and the target
// uses its built-in answers (falcon_scsi.sv).
wire  [1:0] hd_win = {f_lba[5][31:24] >= 8'h7D, f_lba[4][31:24] >= 8'h7D};
reg   [1:0] win_ack = 2'b00;

always @(posedge clk_32)
	for (int k = 0; k < 2; k = k + 1)
		win_ack[k] <= (f_rd[4 + k] | f_wr[4 + k]) & hd_win[k];

wire  [6:0] s_ack = {1'b0, hd_scsi_q ? sd_ack[3:2] | win_ack : win_ack,
                     hd_scsi_q ? 2'b00 : sd_ack[3:2], sd_ack[1:0]};

genvar gi;
generate
	for (gi = 0; gi < 4; gi = gi + 1) begin : g_drive
		// drive gi on Falcon slot ds: SCSI slots 4/5 for the hard disks with hd_scsi
		wire [2:0] ds  = (gi >= 2 && hd_scsi_q) ? 3'(gi + 2) : 3'(gi);
		wire       win = (gi >= 2 && hd_scsi_q) ? hd_win[gi & 1] : 1'b0;
		always @(posedge clk_32)
			if (rd_t2[1]) begin
				if (rd_t2[0]) rd_hi[gi] <= f_buff_din[ds];
				else          rd_lo[gi] <= f_buff_din[ds];
			end
		assign sd_buff_din[16 * gi +: 16] = {rd_hi[gi], rd_lo[gi]};
		assign sd_lba[32 * gi +: 32]      = f_lba[ds];
		assign sd_rd[gi] = f_rd[ds] & ~win;
		assign sd_wr[gi] = f_wr[ds] & ~win;
	end
endgenerate

// ---------------------------------------------------------------------------
// The Falcon
// ---------------------------------------------------------------------------
`ifdef FALCON_FPU_LOCAL
// the 68882 mailbox port (declared before falcon_system uses them, see fpu below)
wire        fpu_req, fpu_we, fpu_ack;
wire [23:1] fpu_addr;
wire  [1:0] fpu_be;
wire [15:0] fpu_wdata, fpu_rdata;
`endif

// NVRAM: the default image has the boot video mode of the monitor type (VGA or RGB/TV) and the
// language and keyboard, so it is built again when they change in the menu (MiSTer: "Reset
// NVRAM"). Not stored on the SD card.
reg   [1:0] monitor_d = 2'b10;
reg   [7:0] lang_d = 8'd0;
reg         nv_init = 1'b0;

always @(posedge clk_32) begin
	monitor_d <= monitor;
	lang_d    <= tos_lang;
	nv_init   <= monitor != monitor_d || tos_lang != lang_d;
end

// the memory configuration changes only with a reset (TOS sizes the memory when it starts)
reg   [3:0] ram_mb_q = 4'd14;
reg   [1:0] fast_n_q = 2'd0;

always @(posedge clk_32)
	if (reset) begin
		ram_mb_q <= ram_mb;
		fast_n_q <= fast_n;
	end

// real floppy drive
wire        wd_sel, wd_rw, wd_irq, wd_drq, fd_side_n;
wire  [1:0] wd_addr, fd_sel_n;
wire  [7:0] wd_din, wd_dout;

wd1772_m65 wd1772 (
	.clk_32(clk_32), .reset(reset | ~real_fd),
	.cpu_sel(wd_sel & real_fd), .cpu_addr(wd_addr), .cpu_rw(wd_rw), .cpu_din(wd_din), .cpu_dout(wd_dout),
	.irq(wd_irq), .drq(wd_drq),
	.motor(rfd_motor), .step(rfd_step), .dir_in(rfd_dir_in), .wgate(rfd_wgate), .wdata(rfd_wdata),
	.rdata(rfd_rdata), .index(rfd_index), .track0(rfd_track0), .wprot(rfd_wprot), .side(rfd_side),
	.retry(fd_retry),
	.absent(~fd_sel_n[1] & fd_sel_n[0]),   // drive B: (not connected while the internal drive is A:)
	.dbg_idx(8'd0), .dbg_entry(), .dbg_count()
);
assign rfd_sel_a = real_fd & ~fd_sel_n[0];
assign rfd_side  = ~fd_side_n;

// NVRAM persistence (see nvb_* above): after a power-on the saved image (if valid) goes into the
// NVRAM while the machine is still in reset; every change of the NVRAM (CPU writes, 10 ms after
// the last one; a new default image) goes into the buffer with the next counter value
localparam N_WAIT = 3'd0, N_CHK = 3'd1, N_REST = 3'd2, N_IDLE = 3'd3, N_COPY = 3'd4, N_CNT0 = 3'd5, N_CNT = 3'd6, N_MARK = 3'd7;
reg   [2:0] nst = N_WAIT;
reg   [5:0] n_i;
reg   [1:0] n_lat;              // read latency of the buffer
reg  [18:0] n_quiet;            // clocks until the copy (10 ms after the last change)
reg         n_pend = 1'b0;
reg         nv_ready_d = 1'b0;
wire        nv_ready, nv_changed;
wire  [7:0] nv_dout;
reg   [5:0] nv_addr;
reg   [7:0] nv_din;
reg         nv_wr;

always @(posedge clk_32) begin
	nvb_we <= 1'b0;
	nv_wr  <= 1'b0;
	nv_ready_d <= nv_ready;
	if (por) begin
		nst <= N_WAIT; n_pend <= 1'b0;
	end
	else case (nst)
		N_WAIT:                          // the default image is built during the first reset
			if (nv_ready && !nv_init) begin
				nvb_addr <= 6'd63; n_lat <= 2'd2; nst <= N_CHK;
			end
		N_CHK:
			if (n_lat != 2'd0) n_lat <= n_lat - 2'd1;
			else if (nvb_dout == 8'hA5) begin
				n_i <= 6'd0; nvb_addr <= 6'd0; n_lat <= 2'd2; nst <= N_REST;
			end
			else begin                   // no saved image: save the defaults
				n_i <= 6'd0; nst <= N_COPY;
			end
		N_REST:
			if (n_lat != 2'd0) n_lat <= n_lat - 2'd1;
			else begin
				nv_addr <= n_i; nv_din <= nvb_dout; nv_wr <= 1'b1;
				if (n_i == 6'd49) nst <= N_IDLE;
				else begin n_i <= n_i + 6'd1; nvb_addr <= n_i + 6'd1; n_lat <= 2'd2; end
			end
		N_IDLE: begin
			if (nv_changed || (nv_ready && !nv_ready_d)) begin
				n_pend <= 1'b1; n_quiet <= CLK_HZ / 100;
			end
			else if (n_pend && n_quiet != 19'd0) n_quiet <= n_quiet - 19'd1;
			else if (n_pend && nv_ready) begin
				n_pend <= 1'b0; n_i <= 6'd0; nst <= N_COPY;
			end
		end
		N_COPY: begin                    // NVRAM -> buffer (nv_dout is combinational)
			nv_addr <= n_i;
			if (nv_addr == n_i && n_lat == 2'd1) begin
				nvb_addr <= n_i; nvb_din <= nv_dout; nvb_we <= 1'b1;
				n_lat <= 2'd0;
				if (n_i == 6'd49) nst <= N_CNT0;
				else n_i <= n_i + 6'd1;
			end
			else n_lat <= 2'd1;
		end
		N_CNT0: begin                    // (byte 49 is written now)
			nvb_addr <= 6'd62; n_lat <= 2'd2; nst <= N_CNT;
		end
		N_CNT:                           // counter + 1
			if (n_lat != 2'd0) n_lat <= n_lat - 2'd1;
			else begin
				nvb_addr <= 6'd62; nvb_din <= nvb_dout + 8'd1; nvb_we <= 1'b1; nst <= N_MARK;
			end
		N_MARK: begin
			nvb_addr <= 6'd63; nvb_din <= 8'hA5; nvb_we <= 1'b1; nst <= N_IDLE;
		end
	endcase
end

wire        DDRAM_BUSY, DDRAM_DOUT_READY, DDRAM_RD, DDRAM_WE;
wire  [7:0] DDRAM_BURSTCNT, DDRAM_BE;
wire [28:0] DDRAM_ADDR;
wire [63:0] DDRAM_DOUT, DDRAM_DIN;

falcon_system #(.CLK_HZ(CLK_HZ)) system (
	.clk(clk_32), .reset(reset), .cold_reset(cold_reset), .por(por),
	.ram_mb(ram_mb_q), .fast_n(fast_n_q), .ram_tos(1'b0), .monitor(monitor), .cpu_turbo(cpu_turbo), .tstat_en(1'b0),
	.ld_wr(ld_wr), .ld_addr(ld_addr), .ld_data(ld_data), .ld_busy(ld_busy),
	.ps2_key(ps2_key), .ps2_mouse(ps2_mouse), .joy0(joy0), .joy1(joy1), .pad0(pad0), .pad1(pad1), .ana0(ana0), .ana1(ana1), .rtc(rtc),
	.nv_lang(tos_lang), .nv_init(nv_init), .nv_addr(nv_addr), .nv_din(nv_din), .nv_wr(nv_wr), .nv_dout(nv_dout),
	.nv_changed(nv_changed), .nv_ready(nv_ready),
	.img_mounted(s_mounted), .img_readonly(s_ro), .img_size({32'd0, s_size}),
	.sd_lba(f_lba), .sd_rd(f_rd), .sd_wr(f_wr), .sd_blk_cnt(f_blk_cnt), .sd_ack(s_ack),
	.sd_buff_addr(f_buff_addr), .sd_buff_dout(f_buff_dout), .sd_buff_din(f_buff_din), .sd_buff_wr(f_buff_wr),
	.r(r), .g(g), .b(b), .hsync(hsync), .vsync(vsync), .hblank(hblank), .vblank(vblank), .ce_pix(ce_pix),
	.audio_l(audio_l), .audio_r(audio_r),
	.ext_fd(real_fd), .wd_sel(wd_sel), .wd_addr(wd_addr), .wd_rw(wd_rw), .wd_din(wd_din),
